import{_ as e,c as o,o as t,b0 as r}from"./chunks/framework.Dmsv_Tiv.js";const n="/media-docs/assets/image-20251216095951085.CY4w56jT.png",i="/media-docs/assets/image-20251216101912965._8gl7uhb.png",l="/media-docs/assets/image-20251216162031931.BnqHDiIF.png",_=JSON.parse('{"title":"LV005-MP4文件分析","description":null,"frontmatter":{"title":"LV005-MP4文件分析","date":"2025-12-16T16:17:03.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/avtools/file-analysis/126b1a8baba714e28be84f52","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-16T16:17:03.334Z","fulluuid":"28be84f52cbf4a5cbfba9a51401b7149","useduuid":"28be84f52"}},"headers":[],"relativePath":"sdoc/avtools/file-analysis/126b1a8baba714e28be84f52.md","filePath":"sdoc/80-常用工具/15-文件分析/LV005-MP4文件分析.md","lastUpdated":1767537778000}'),s={name:"sdoc/avtools/file-analysis/126b1a8baba714e28be84f52.md"};function d(c,a,p,h,m,b){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="lv005-mp4文件分析" tabindex="-1">LV005-MP4文件分析 <a class="header-anchor" href="#lv005-mp4文件分析" aria-label="Permalink to &quot;LV005-MP4文件分析&quot;">​</a></h1><h2 id="一、mp4info" tabindex="-1">一、mp4info <a class="header-anchor" href="#一、mp4info" aria-label="Permalink to &quot;一、mp4info&quot;">​</a></h2><h4 id="_1-简介" tabindex="-1">1. 简介 <a class="header-anchor" href="#_1-简介" aria-label="Permalink to &quot;1. 简介&quot;">​</a></h4><p><code>mp4info</code> 是一款专为解析 MP4 文件而设计的工具，而且是可视化的工具，可以将 MP4 中的各个 Box 解析出来，并将其中的数据展现出来。</p><p>能帮助我们深入了解 MP4 文件的内部结构和详细信息。通过使用 <code>mp4info</code>，可以轻松获取 MP4 文件的元数据、编码信息、轨道信息等关键数据，从而更好地管理和优化我们的视频资源。</p><p>它不仅可以清晰看到各个 box 的组成和层次，同时可以分离里面的音视频文件，当然这个分离出的原始码流不能直接播放。其次可以看到音视频的时间戳等信息，这对于解决一些花屏和播放跳秒等问题排查有帮助。</p><h3 id="_2-下载与安装" tabindex="-1">2. 下载与安装 <a class="header-anchor" href="#_2-下载与安装" aria-label="Permalink to &quot;2. 下载与安装&quot;">​</a></h3><p>官网没找到，但是网上有很多下载的链接，我当时下的这个：<a href="https://www.jb51.net/softs/583311.html" target="_blank" rel="noreferrer">mp4info 下载 mp4info(MP4 信息查看工具) v1.7 免费绿色版 下载-脚本之家</a>，选下面的普通下载地址，不然会被安装一些其他莫名其妙的软件。</p><h3 id="_3-基本用法" tabindex="-1">3. 基本用法 <a class="header-anchor" href="#_3-基本用法" aria-label="Permalink to &quot;3. 基本用法&quot;">​</a></h3><h4 id="_3-1-查看文件结构" tabindex="-1">3.1 查看文件结构 <a class="header-anchor" href="#_3-1-查看文件结构" aria-label="Permalink to &quot;3.1 查看文件结构&quot;">​</a></h4><p>上面的软件是免安装的，我们可以用这个文件测试一下：<a href="http://vjs.zencdn.net/v/oceans.mp4" target="_blank" rel="noreferrer">vjs.zencdn.net/v/oceans.mp4</a>，这是一个 MP4 封装的视频，可以下载下来打开看一下：</p><p><img src="'+n+'" alt="image-20251216095951085"></p><h4 id="_3-2-查看音视频帧" tabindex="-1">3.2 查看音视频帧 <a class="header-anchor" href="#_3-2-查看音视频帧" aria-label="Permalink to &quot;3.2 查看音视频帧&quot;">​</a></h4><p><img src="'+i+'" alt="image-20251216101912965"></p><h2 id="二、mp4-reader" tabindex="-1">二、MP4 Reader <a class="header-anchor" href="#二、mp4-reader" aria-label="Permalink to &quot;二、MP4 Reader&quot;">​</a></h2><h3 id="_1-简介-1" tabindex="-1">1. 简介 <a class="header-anchor" href="#_1-简介-1" aria-label="Permalink to &quot;1. 简介&quot;">​</a></h3><p>mp4reader是一款专业的MP4文件分析工具，其功能远超常见的mp4info.exe。它不仅能够分析多种mp4info.exe无法处理的MP4文件，而且还能以十六进制格式显示相应的box信息，为用户提供更为详尽的文件结构分析。</p><h3 id="_2-下载与安装-1" tabindex="-1">2. 下载与安装 <a class="header-anchor" href="#_2-下载与安装-1" aria-label="Permalink to &quot;2. 下载与安装&quot;">​</a></h3><p>没找到官网，但是网上有很多下载链接，例如 [MP4格式深度解析工具mp4reader - AtomGit | GitCode](<a href="https://gitcode.com/Universal-Tool/c53cf/blob/main/MP4" target="_blank" rel="noreferrer">https://gitcode.com/Universal-Tool/c53cf/blob/main/MP4</a> Reader-0.9.0.6.zip)</p><h3 id="_3-基本用法-1" tabindex="-1">3. 基本用法 <a class="header-anchor" href="#_3-基本用法-1" aria-label="Permalink to &quot;3. 基本用法&quot;">​</a></h3><p>直接打开即可：</p><p><img src="'+l+'" alt="image-20251216162031931"></p><blockquote><p>参考资料：</p><p><a href="https://www.bento4.com/documentation/mp4info/" target="_blank" rel="noreferrer">mp4info - Bento4</a></p><p><a href="https://blog.csdn.net/weixin_42389113/article/details/153106884" target="_blank" rel="noreferrer">MP4 文件元信息分析工具 mp4info 详解与实战应用-CSDN 博客</a></p></blockquote>',23)])])}const u=e(s,[["render",d]]);export{_ as __pageData,u as default};
